#include <string>
#include <vector>

std::vector<int> blocked_counts(int capacity, const std::string& events) {
    int items = 0, blocked_push = 0, blocked_pop = 0;
    for (char e : events) {
        if (e == 'P') {
            if (items == capacity) ++blocked_push;
            else ++items;
        } else {
            if (items == 0) ++blocked_pop;
            else --items;
        }
    }
    return {blocked_push, blocked_pop, items};
}
